esign system\n\nBreaking changes:\n- Removed newsletter-compact component file\n- Updated home.component.ts to use <app-newsletter [variant]=\"''full''\">\n- Updated post-detail.component.ts to use <app-newsletter [variant]=\"''compact''\">","tree":{"sha":"fe04880da9069a1b11993e37f9f218023e02850a","url":"https://api.github.com/repos/branzan-pablo/CodeFlow-/git/trees/fe04880da9069a1b11993e37f9f218023e02850a"},"url":"https://api.github.com/repos/branzan-pablo/CodeFlow-/git/commits/8be66ecc2ddb79639eb1158576844c93050e31d5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/176821849?v=4","events_url":"https://api.github.com/users/branzan-pablo/events{/privacy}","followers_url":"https://api.github.com/users/branzan-pablo/followers","following_url":"https://api.github.com/users/branzan-pablo/following{/other_user}","gists_url":"https://api.github.com/users/branzan-pablo/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/branzan-pablo","id":176821849,"login":"branzan-pablo","node_id":"U_kgDOCooWWQ","organizations_url":"https://api.github.com/users/branzan-pablo/orgs","received_events_url":"https://api.github.com/users/branzan-pablo/received_events","repos_url":"https://api.github.com/users/branzan-pablo/repos","site_admin":false,"starred_url":"https://api.github.com/users/branzan-pablo/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/branzan-pablo/subscriptions","type":"User","url":"https://api.github.com/users/branzan-pablo","user_view_type":"public"},"html_url":"https://github.com/branzan-pablo/CodeFlow-/commit/8be66ecc2ddb79639eb1158576844c93050e31d5","node_id":"C_kwDOQBJ8WNoAKDhiZTY2ZWNjMmRkYjc5NjM5ZWIxMTU4NTc2ODQ0YzkzMDUwZTMxZDU","parents":[{"html_url":"https://github.com/branzan-pablo/CodeFlow-/commit/4243276592896050d6c98566ec5e683d6dad3463","sha":"4243276592896050d6c98566ec5e683d6dad3463","url":"https://ap